// FreeLang Science - 수학 모듈

export const SCI_MATH_CONSTANTS = `
// 수학 상수
const PI: float = 3.141592653589793
const E:  float = 2.718281828459045
const TAU: float = 6.283185307179586
const PHI: float = 1.618033988749895  // 황금비
const INF: float = 1e308
`;

export const SCI_MATH_FUNCTIONS = `
// 기본 수학 함수
fn abs(x: float) -> float { if x < 0 { return -x } return x }
fn sign(x: float) -> float { if x > 0 { return 1.0 } if x < 0 { return -1.0 } return 0.0 }
fn min(a: float, b: float) -> float { if a < b { return a } return b }
fn max(a: float, b: float) -> float { if a > b { return a } return b }
fn clamp(x: float, lo: float, hi: float) -> float { return min(max(x, lo), hi) }

// 반올림
fn floor(x: float) -> float { return __builtin_floor(x) }
fn ceil(x: float)  -> float { return __builtin_ceil(x) }
fn round(x: float) -> float { return __builtin_round(x) }

// 거듭제곱 / 제곱근
fn pow(base: float, exp: float) -> float { return __builtin_pow(base, exp) }
fn sqrt(x: float) -> float { return __builtin_sqrt(x) }
fn cbrt(x: float) -> float { return __builtin_cbrt(x) }

// 로그 / 지수
fn exp(x: float)   -> float { return __builtin_exp(x) }
fn ln(x: float)    -> float { return __builtin_log(x) }
fn log2(x: float)  -> float { return __builtin_log2(x) }
fn log10(x: float) -> float { return __builtin_log10(x) }
fn log(x: float, base: float) -> float { return ln(x) / ln(base) }

// 삼각함수 (라디안)
fn sin(x: float)   -> float { return __builtin_sin(x) }
fn cos(x: float)   -> float { return __builtin_cos(x) }
fn tan(x: float)   -> float { return __builtin_tan(x) }
fn asin(x: float)  -> float { return __builtin_asin(x) }
fn acos(x: float)  -> float { return __builtin_acos(x) }
fn atan(x: float)  -> float { return __builtin_atan(x) }
fn atan2(y: float, x: float) -> float { return __builtin_atan2(y, x) }

// 쌍곡선 함수
fn sinh(x: float)  -> float { return __builtin_sinh(x) }
fn cosh(x: float)  -> float { return __builtin_cosh(x) }
fn tanh(x: float)  -> float { return __builtin_tanh(x) }

