// FreeLang Science - Math Module v4
// 타언어 최소 개입 (순수 FreeLang V4 구현)

// ============ CONSTANTS ============
const PI: f64 = 3.141592653589793
const E: f64 = 2.718281828459045
const TAU: f64 = 6.283185307179586
const PHI: f64 = 1.618033988749895    // 황금비
const SQRT2: f64 = 1.414213562373095
const SQRT3: f64 = 1.732050807568877
const LN2: f64 = 0.693147180559945
const LN10: f64 = 2.302585092994046
const LOG2E: f64 = 1.442695040888963
const LOG10E: f64 = 0.434294481903252

// ============ BASIC OPERATIONS ============

// 절댓값
fn abs(x: f64) -> f64 {
  if x < 0.0 { return -x }
  return x
}

// 부호 반환 (-1, 0, 1)
fn sign(x: f64) -> f64 {
  if x > 0.0 { return 1.0 }
  if x < 0.0 { return -1.0 }
  return 0.0
}

// 최솟값
fn min(a: f64, b: f64) -> f64 {
  if a < b { return a }
  return b
}

// 최댓값
fn max(a: f64, b: f64) -> f64 {
  if a > b { return a }
  return b
}

// 범위 제한
fn clamp(x: f64, lo: f64, hi: f64) -> f64 {
  if x < lo { return lo }
  if x > hi { return hi }
  return x
}

// ============ ROUNDING ============

// 아래로 반올림 (floor)
fn floor(x: f64) -> f64 {
  var n = i64(x)
  if x >= 0.0 { return f64(n) }
  return f64(n) - 1.0
}

// 위로 반올림 (ceil)
fn ceil(x: f64) -> f64 {
  var n = i64(x)
  if x <= 0.0 { return f64(n) }
  return f64(n) + 1.0
}

// 반올림 (round)
fn round(x: f64) -> f64 {
  if x >= 0.0 { return floor(x + 0.5) }
  return ceil(x - 0.5)
}

// ============ POWER & ROOT ============

// 거듭제곱 (pow) - 정수 지수 버전
fn pow_int(base: f64, exp: i64) -> f64 {
  if exp == 0 { return 1.0 }
  if exp < 0 { return 1.0 / pow_int(base, -exp) }

  var result = 1.0
  var b = base
  var e = exp

  // 이분 거듭제곱법
  while e > 0 {
    if e % 2 == 1 {
      result = result * b
    }
    b = b * b
    e = e / 2
  }
  return result
}

// 제곱근 (sqrt) - 뉴턴 방법
fn sqrt(x: f64) -> f64 {
  if x < 0.0 { return -1.0 }  // Error case
  if x == 0.0 { return 0.0 }

  var guess = x / 2.0
  var prev = 0.0
  var eps = 1e-15

  while abs(guess - prev) > eps {
    prev = guess
    guess = (guess + x / guess) / 2.0
  }
  return guess
}

// 세제곱근 (cbrt)
fn cbrt(x: f64) -> f64 {
  if x == 0.0 { return 0.0 }
  var sign = sign(x)
  var abs_x = abs(x)
  var guess = abs_x / 3.0
  var prev = 0.0
  var eps = 1e-15

  while abs(guess - prev) > eps {
    prev = guess
    guess = (2.0 * guess + abs_x / (guess * guess)) / 3.0
  }
  return sign * guess
}

// ============ EXPONENTIAL & LOGARITHM ============

// 자연지수 (e^x) - 테일러 급수
fn exp(x: f64) -> f64 {
  var result = 1.0
  var term = 1.0
  var n = 1.0

  var i = 0
  while i < 50 {
    term = term * x / n
    result = result + term
    if abs(term) < 1e-15 { break }
    i = i + 1
    n = n + 1.0
  }
  return result
}

// 자연로그 (ln) - 테일러 급수
fn ln(x: f64) -> f64 {
  if x <= 0.0 { return -1.0 }  // Error
  if x == 1.0 { return 0.0 }

  // x를 1에 가까운 값으로 정규화
  var n = 0.0
  var y = x
  while y > 2.0 {
    y = y / E
    n = n + 1.0
  }
  while y < 0.5 {
    y = y * E
    n = n - 1.0
  }

  // (x-1)/(x+1) 형태로 변환
  var z = (y - 1.0) / (y + 1.0)
  var z2 = z * z
  var result = 0.0
  var term = z

  var i = 0
  while i < 100 {
    result = result + term / (2.0 * f64(i) + 1.0)
    term = term * z2
    if abs(term) < 1e-15 { break }
    i = i + 1
  }

  return 2.0 * result + n
}

// 상용로그 (log10)
fn log10(x: f64) -> f64 {
  return ln(x) / ln(10.0)
}

// 2진로그 (log2)
fn log2(x: f64) -> f64 {
  return ln(x) / LN2
}

// 임의 밑의 로그
fn log(x: f64, base: f64) -> f64 {
  return ln(x) / ln(base)
}

// ============ TRIGONOMETRIC FUNCTIONS ============

// 정현파 (sin) - 테일러 급수
fn sin(x: f64) -> f64 {
  // x를 [-π, π] 범위로 정규화
  var reduced_x = x
  while reduced_x > PI {
    reduced_x = reduced_x - TAU
  }
  while reduced_x < -PI {
    reduced_x = reduced_x + TAU
  }

  var result = 0.0
  var term = reduced_x
  var x2 = reduced_x * reduced_x

  var i = 1
  while i < 50 {
    result = result + term
    term = term * (-x2) / (f64(2*i) * f64(2*i + 1))
    if abs(term) < 1e-15 { break }
    i = i + 1
  }
  return result
}

// 코사인 (cos)
fn cos(x: f64) -> f64 {
  // x를 [-π, π] 범위로 정규화
  var reduced_x = x
  while reduced_x > PI {
    reduced_x = reduced_x - TAU
  }
  while reduced_x < -PI {
    reduced_x = reduced_x + TAU
  }

  var result = 1.0
  var term = 1.0
  var x2 = reduced_x * reduced_x

  var i = 1
  while i < 50 {
    term = term * (-x2) / (f64(2*i - 1) * f64(2*i))
    result = result + term
    if abs(term) < 1e-15 { break }
    i = i + 1
  }
  return result
}

// 탄젠트 (tan)
fn tan(x: f64) -> f64 {
  var c = cos(x)
  if abs(c) < 1e-15 { return 0.0 }  // undefined
  return sin(x) / c
}

// 역정현 (asin)
fn asin(x: f64) -> f64 {
  if abs(x) > 1.0 { return 0.0 }  // Error
  if x == 0.0 { return 0.0 }

  var result = x
  var numerator = x
  var denominator = 1.0
  var x2 = x * x

  var n = 1
  while n < 50 {
    numerator = numerator * x2 * f64(2*n - 1) / f64(2*n)
    denominator = f64(2*n + 1)
    result = result + numerator / denominator
    if abs(numerator) < 1e-15 { break }
    n = n + 1
  }
  return result
}

// 역코사인 (acos)
fn acos(x: f64) -> f64 {
  return PI / 2.0 - asin(x)
}

// 역탄젠트 (atan)
fn atan(x: f64) -> f64 {
  if abs(x) > 1.0 {
    return sign(x) * (PI / 2.0) - atan(1.0 / x)
  }

  var result = 0.0
  var x_power = x
  var x2 = x * x

  var n = 0
  while n < 50 {
    result = result + x_power / f64(2*n + 1)
    x_power = x_power * (-x2)
    if abs(x_power) < 1e-15 { break }
    n = n + 1
  }
  return result
}

// 두 변수 역탄젠트 (atan2)
fn atan2(y: f64, x: f64) -> f64 {
  if x > 0.0 { return atan(y / x) }
  if x < 0.0 && y >= 0.0 { return atan(y / x) + PI }
  if x < 0.0 && y < 0.0 { return atan(y / x) - PI }
  if x == 0.0 && y > 0.0 { return PI / 2.0 }
  if x == 0.0 && y < 0.0 { return -PI / 2.0 }
  return 0.0  // undefined
}

// ============ HYPERBOLIC FUNCTIONS ============

// 쌍곡선 정현 (sinh)
fn sinh(x: f64) -> f64 {
  return (exp(x) - exp(-x)) / 2.0
}

// 쌍곡선 코사인 (cosh)
fn cosh(x: f64) -> f64 {
  return (exp(x) + exp(-x)) / 2.0
}

// 쌍곡선 탄젠트 (tanh)
fn tanh(x: f64) -> f64 {
  var e2x = exp(2.0 * x)
  return (e2x - 1.0) / (e2x + 1.0)
}

// ============ SPECIAL FUNCTIONS ============

// 최대공약수 (GCD)
fn gcd(a: i64, b: i64) -> i64 {
  if b == 0 { return a }
  return gcd(b, a % b)
}

// 최소공배수 (LCM)
fn lcm(a: i64, b: i64) -> i64 {
  return (a * b) / gcd(a, b)
}

// 계승 (factorial)
fn factorial(n: i64) -> i64 {
  if n <= 1 { return 1 }
  return n * factorial(n - 1)
}

// 조합 nCr
fn combination(n: i64, r: i64) -> i64 {
  if r > n { return 0 }
  if r == 0 || r == n { return 1 }
  return factorial(n) / (factorial(r) * factorial(n - r))
}

// 순열 nPr
fn permutation(n: i64, r: i64) -> i64 {
  if r > n { return 0 }
  return factorial(n) / factorial(n - r)
}

// ============ VECTOR OPERATIONS (배열 연산) ============

// 벡터 크기 (norm)
fn vector_norm(v: f64[]) -> f64 {
  var sum = 0.0
  var i = 0
  while i < len(v) {
    sum = sum + v[i] * v[i]
    i = i + 1
  }
  return sqrt(sum)
}

// 벡터 내적 (dot product)
fn dot_product(a: f64[], b: f64[]) -> f64 {
  var result = 0.0
  var i = 0
  var len_a = len(a)
  while i < len_a {
    result = result + a[i] * b[i]
    i = i + 1
  }
  return result
}

// 벡터 스칼라 곱셈
fn scalar_multiply(v: f64[], scalar: f64) -> f64[] {
  var result: f64[] = [0.0]
  var i = 0
  while i < len(v) {
    push(result, v[i] * scalar)
    i = i + 1
  }
  pop(result)  // 초기 0.0 제거
  return result
}

// ============ END OF MATH MODULE ============

