  var i = 0
  while i < len(arr) {
    result = result + arr[i]
    i = i + 1
  }
  return result
}

// 평균 (mean)
fn mean(arr: f64[]) -> f64 {
  if len(arr) == 0 { return 0.0 }
  return sum(arr) / f64(len(arr))
}

// 중앙값 (median)
fn median(arr: f64[]) -> f64 {
  if len(arr) == 0 { return 0.0 }

  var n = len(arr)
  // 정렬 필요 (삽입 정렬)
  var sorted: f64[] = [0.0]
  var i = 0
  while i < n {
    push(sorted, arr[i])
    i = i + 1
  }
  pop(sorted)  // 초기 0.0 제거

  // 삽입 정렬
  var j = 1
  while j < len(sorted) {
    var key = sorted[j]
    var k = j - 1
    while k >= 0 && sorted[k] > key {
      sorted[k + 1] = sorted[k]
      k = k - 1
    }
    sorted[k + 1] = key
    j = j + 1
  }

  if len(sorted) % 2 == 1 {
    return sorted[len(sorted) / 2]
  }
  return (sorted[len(sorted) / 2 - 1] + sorted[len(sorted) / 2]) / 2.0
}

// 최솟값 (min)
fn min_val(arr: f64[]) -> f64 {
  if len(arr) == 0 { return 0.0 }
  var result = arr[0]
  var i = 1
  while i < len(arr) {
    if arr[i] < result { result = arr[i] }
    i = i + 1
  }
  return result
}

// 최댓값 (max)
fn max_val(arr: f64[]) -> f64 {
  if len(arr) == 0 { return 0.0 }
  var result = arr[0]
  var i = 1
  while i < len(arr) {
    if arr[i] > result { result = arr[i] }
    i = i + 1
  }
  return result
}

// 범위 (range)
fn range(arr: f64[]) -> f64 {
  return max_val(arr) - min_val(arr)
}

// ============ DISPERSION MEASURES ============

// 분산 (variance)
fn variance(arr: f64[]) -> f64 {
  if len(arr) == 0 { return 0.0 }

  var m = mean(arr)
  var sum_sq_diff = 0.0
  var i = 0

  while i < len(arr) {
    var diff = arr[i] - m
    sum_sq_diff = sum_sq_diff + diff * diff
    i = i + 1
  }

  return sum_sq_diff / f64(len(arr))
}

// 표본 분산 (sample variance)
fn sample_variance(arr: f64[]) -> f64 {
  if len(arr) <= 1 { return 0.0 }

  var m = mean(arr)
  var sum_sq_diff = 0.0
  var i = 0

  while i < len(arr) {
    var diff = arr[i] - m
    sum_sq_diff = sum_sq_diff + diff * diff
    i = i + 1
  }

  return sum_sq_diff / f64(len(arr) - 1)
}

// 표준편차 (standard deviation)
fn stdev(arr: f64[]) -> f64 {
  var v = variance(arr)
  if v < 0.0 { return 0.0 }

  // sqrt 구현 (뉴턴 방법)
  var guess = v / 2.0
  var prev = 0.0
  var eps = 1e-15

  while abs(guess - prev) > eps {
    prev = guess
    guess = (guess + v / guess) / 2.0
  }
  return guess
}

// 표본 표준편차
fn sample_stdev(arr: f64[]) -> f64 {
  var v = sample_variance(arr)
  if v < 0.0 { return 0.0 }

  var guess = v / 2.0
  var prev = 0.0
  var eps = 1e-15

  while abs(guess - prev) > eps {
    prev = guess
    guess = (guess + v / guess) / 2.0
  }
  return guess
}

// ============ ADVANCED STATISTICS ============

// 공분산 (covariance)
fn covariance(x: f64[], y: f64[]) -> f64 {
  if len(x) == 0 { return 0.0 }
  if len(x) != len(y) { return 0.0 }

  var mean_x = mean(x)
  var mean_y = mean(y)
  var sum_product = 0.0
  var i = 0

  while i < len(x) {
    sum_product = sum_product + (x[i] - mean_x) * (y[i] - mean_y)
    i = i + 1
  }

  return sum_product / f64(len(x))
}

// 상관계수 (correlation coefficient - Pearson)
fn correlation(x: f64[], y: f64[]) -> f64 {
  if len(x) == 0 { return 0.0 }
  if len(x) != len(y) { return 0.0 }

  var cov = covariance(x, y)
  var std_x = stdev(x)
  var std_y = stdev(y)

  if std_x == 0.0 || std_y == 0.0 { return 0.0 }

  return cov / (std_x * std_y)
}

// ============ QUANTILES ============

// 분위수 (quantile)
fn quantile(arr: f64[], q: f64) -> f64 {
  if len(arr) == 0 { return 0.0 }
  if q < 0.0 || q > 1.0 { return 0.0 }

  var n = len(arr)
  // 정렬
  var sorted: f64[] = [0.0]
  var i = 0
  while i < n {
    push(sorted, arr[i])
    i = i + 1
  }
  pop(sorted)

  // 삽입 정렬
  var j = 1
  while j < len(sorted) {
    var key = sorted[j]
    var k = j - 1
    while k >= 0 && sorted[k] > key {
      sorted[k + 1] = sorted[k]
      k = k - 1
    }
    sorted[k + 1] = key
    j = j + 1
  }

  var pos = q * f64(len(sorted) - 1)
  var lower = i64(pos)
  var upper = lower + 1

  if upper >= len(sorted) { return sorted[lower] }

  var frac = pos - f64(lower)
  return sorted[lower] * (1.0 - frac) + sorted[upper] * frac
}

// 사분위수 (quartile)
fn quartile(arr: f64[], q: i64) -> f64 {
  match q {
    0 => return min_val(arr),
    1 => return quantile(arr, 0.25),
    2 => return quantile(arr, 0.5),
    3 => return quantile(arr, 0.75),
    4 => return max_val(arr),
    _ => return 0.0
  }
}

// ============ DISTRIBUTION FUNCTIONS ============

// 정규분포 PDF (확률밀도함수)
fn normal_pdf(x: f64, mean: f64, std: f64) -> f64 {
  if std <= 0.0 { return 0.0 }

  var PI = 3.141592653589793
  var E = 2.718281828459045
  var z = (x - mean) / std
  var coeff = 1.0 / (std * sqrt(2.0 * PI))
  var exponent = -0.5 * z * z

  // e^exponent 계산 (테일러 급수)
  var e_exp = 1.0
  var term = 1.0
  var i = 1
  while i < 50 {
    term = term * exponent / f64(i)
    e_exp = e_exp + term
    if abs(term) < 1e-15 { break }
    i = i + 1
  }

  return coeff * e_exp
}

// ============ HELPER FUNCTIONS ============

// 절댓값
fn abs(x: f64) -> f64 {
  if x < 0.0 { return -x }
  return x
}

// 제곱근 (뉴턴 방법)
fn sqrt(x: f64) -> f64 {
  if x < 0.0 { return 0.0 }
  if x == 0.0 { return 0.0 }

  var guess = x / 2.0
  var prev = 0.0
  var eps = 1e-15

  while abs(guess - prev) > eps {
    prev = guess
    guess = (guess + x / guess) / 2.0
  }
  return guess
}

