# 📖 언어 가이드

FreeLang의 모든 주요 기능을 심화 학습하세요.

## 타입 시스템

### 기본 타입

```freelang
// 정수
let a: i8 = 127
let b: i16 = 32767
let c: i32 = 2147483647
let d: i64 = 9223372036854775807

// 부호 없는 정수
let e: u8 = 255
let f: u16 = 65535
let g: u32 = 4294967295
let h: u64 = 18446744073709551615

// 실수
let x: f32 = 3.14
let y: f64 = 3.141592653589793

// 문자열 & 문자
let name: string = "Alice"
let initial: char = 'A'

// 불리언
let is_active: bool = true
let is_empty: bool = false

// 단위 타입 (void)
fn do_nothing() -> void {
  println("Nothing")
}
```

### 복합 타입

#### 배열

```freelang
// 고정 크기 배열
let fixed: i64[5] = [1, 2, 3, 4, 5]

// 동적 배열
let mut dynamic: i64[] = []
dynamic.push(1)
dynamic.push(2)
println(len(dynamic))  // 2

// 배열 순회
for i in range(len(dynamic)) {
  println(dynamic[i])
}

// 고차 함수 (map, filter)
let numbers: i64[] = [1, 2, 3, 4, 5]
let doubled = numbers.map(fn(x: i64) -> i64 { x * 2 })
let evens = numbers.filter(fn(x: i64) -> bool { x % 2 == 0 })
```

#### 구조체

```freelang
struct User {
  id: i64,
  name: string,
  email: string,
  is_active: bool
}

// 구조체 생성
let user = User {
  id: 1,
  name: "Alice",
  email: "alice@example.com",
  is_active: true
}

// 필드 접근
println(user.name)    // Alice

// 구조체 메서드
impl User {
  fn is_admin(self) -> bool {
    return self.id == 1
  }

  fn activate(mut self) -> void {
    self.is_active = true
  }
}

let admin = user.is_admin()  // false or true
```

#### Enum (열거형)

```freelang
enum Status {
  Pending,
  Active,
  Inactive,
  Deleted(string)  // 데이터 포함
}

let status = Status::Active
let reason = Status::Deleted("User requested")

// 패턴 매칭
match status {
  Status::Active => println("Active"),
  Status::Pending => println("Pending"),
  Status::Deleted(reason) => println("Deleted: " + reason),
  _ => println("Unknown")
}
```

#### Option & Result

```freelang
// Option: 값이 있을 수도, 없을 수도 있음
enum Option<T> {
  Some(T),
  None
}

// Result: 성공 또는 실패
enum Result<T, E> {
  Ok(T),
  Err(E)
}

// 사용 예시
fn find_user(id: i64) -> Option<User> {
  if id == 1 {
    return Some(User { ... })
  }
  return None
}

fn parse_number(s: string) -> Result<i64, string> {
  // 파싱 로직
  if is_valid_number(s) {
    return Ok(int_parse(s))
  }
  return Err("Invalid number")
}
```

## 제어 흐름

### if/else if/else

```freelang
let age = 25

if age < 13 {
  println("Child")
} else if age < 18 {
  println("Teenager")
} else if age < 65 {
  println("Adult")
} else {
  println("Senior")
}

// if 표현식 (값 반환)
let category = if age >= 18 { "Adult" } else { "Child" }
```

### match (패턴 매칭)

```freelang
enum Color {
  Red,
  Green,
  Blue,
  Custom(string)
}

let color = Color::Red

match color {
  Color::Red => println("🔴 Red"),
  Color::Green => println("🟢 Green"),
  Color::Blue => println("🔵 Blue"),
  Color::Custom(name) => println("Custom: " + name),
  _ => println("Unknown")
}

// match 표현식
let rgb = match color {
  Color::Red => "255,0,0",
  Color::Green => "0,255,0",
  Color::Blue => "0,0,255",
  Color::Custom(name) => "custom",
  _ => "unknown"
}
```

### 루프

```freelang
// for 루프
for i in range(10) {
  println(i)  // 0~9
}

// for-in 루프 (배열)
let items = ["apple", "banana", "cherry"]
for item in items {
  println(item)
}

// while 루프
let mut count = 0
while count < 5 {
  println(count)
  count = count + 1
}

// loop (무한 루프)
loop {
  println("Infinite")
  if should_break { break }
}

// break & continue
for i in range(10) {
  if i == 3 { continue }    // 3 건너뛰기
  if i == 7 { break }       // 7에서 종료
  println(i)
}
```

## 함수

### 함수 정의

```freelang
// 기본 함수
fn add(a: i64, b: i64) -> i64 {
  return a + b
}

// 암시적 반환
fn multiply(x: i64, y: i64) -> i64 {
  x * y  // return 생략 가능
}

// 여러 반환값 (튜플)
fn divmod(a: i64, b: i64) -> (i64, i64) {
  return (a / b, a % b)
}

let (quotient, remainder) = divmod(17, 5)
println(quotient)    // 3
println(remainder)   // 2

// 기본값
fn greet(name: string = "Guest") -> void {
  println("Hello, " + name)
}

greet()              // Hello, Guest
greet("Alice")       // Hello, Alice
```

### 고차 함수

```freelang
// 함수를 매개변수로
fn apply(f: fn(i64) -> i64, x: i64) -> i64 {
  return f(x)
}

let square = fn(x: i64) -> i64 { x * x }
let result = apply(square, 5)  // 25

// 클로저
fn make_adder(n: i64) -> fn(i64) -> i64 {
  return fn(x: i64) -> i64 { x + n }
}

let add_5 = make_adder(5)
println(add_5(10))   // 15
```

## 메모리 관리

### 소유권 (Ownership)

```freelang
let s1: string = "Hello"
let s2: string = s1  // s1의 소유권이 s2로 이동

// println(s1)  // ❌ 오류: s1은 더 이상 유효하지 않음
println(s2)   // ✓ OK

// 참조로 해결
fn print_string(s: &string) -> void {
  println(s)
}

let s = "World"
print_string(&s)
println(s)  // ✓ s는 여전히 유효
```

### 가변성 (Mutability)

```freelang
let mut x = 5      // 가변 변수
x = 10             // ✓ OK

let y = 20         // 불변 변수
// y = 25           // ❌ 오류: 불변

// 가변 참조
fn increment(n: &mut i64) -> void {
  *n = *n + 1
}

let mut count = 0
increment(&mut count)
println(count)     // 1
```

## 에러 처리

### try-catch (?)

```freelang
fn divide(a: i64, b: i64) -> Result<i64, string> {
  if b == 0 {
    return Err("Division by zero")
  }
  return Ok(a / b)
}

fn safe_divide() -> Result<i64, string> {
  let result = divide(10, 2)?  // ? 연산자로 에러 전파
  return Ok(result * 2)
}

// 사용
match safe_divide() {
  Ok(value) => println("Result: " + str(value)),
  Err(msg) => println("Error: " + msg)
}
```

### panic!

```freelang
fn assert_positive(x: i64) -> void {
  if x <= 0 {
    panic("Expected positive number")
  }
}

// panic!은 프로그램 종료
```

## 고급 기능

### 제네릭

```freelang
fn swap<T>(a: T, b: T) -> (T, T) {
  return (b, a)
}

let (x, y) = swap(5, 10)
let (s1, s2) = swap("Hello", "World")

// 제네릭 구조체
struct Pair<T> {
  first: T,
  second: T
}

let int_pair = Pair { first: 1, second: 2 }
let str_pair = Pair { first: "a", second: "b" }
```

### 트레이트 (Trait)

```freelang
trait Drawable {
  fn draw(self) -> void
}

struct Circle {
  radius: f64
}

impl Drawable for Circle {
  fn draw(self) -> void {
    println("Drawing circle with radius: " + str(self.radius))
  }
}

let circle = Circle { radius: 5.0 }
circle.draw()
```

### 모듈

```freelang
// math.fl
module math {
  pub fn add(a: i64, b: i64) -> i64 {
    return a + b
  }

  fn internal_helper() -> void {
    // private 함수
  }
}

// main.fl
use math

fn main() {
  let result = math::add(5, 3)
  println(result)  // 8
}
```

## 성능 최적화

### Inline

```freelang
@inline
fn small_function(x: i64) -> i64 {
  return x * 2
}
```

### Const

```freelang
const PI: f64 = 3.141592653589793
const MAX_SIZE: i64 = 1000

@const
fn compute_table() -> i64[] {
  // 컴파일 타임에 계산
}
```

### Unsafe (주의해서 사용!)

```freelang
unsafe fn access_raw_pointer(ptr: *i64) -> i64 {
  return *ptr
}
```

---

**더 깊이 있는 학습을 원하신가요?** [API 레퍼런스](/docs/api-reference)를 확인하세요!

