```freelang
fn bubble_sort(arr: &mut i64[]) -> void {
  let n = len(arr)
  let mut i = 0
  while i < n {
    let mut j = 0
    while j < n - i - 1 {
      if arr[j] > arr[j + 1] {
        let temp = arr[j]
        arr[j] = arr[j + 1]
        arr[j + 1] = temp
      }
      j = j + 1
    }
    i = i + 1
  }
}

fn binary_search(arr: i64[], target: i64) -> i64 {
  let mut left = 0
  let mut right = len(arr) - 1

  while left <= right {
    let mid = (left + right) / 2
    if arr[mid] == target {
      return mid
    } else if arr[mid] < target {
      left = mid + 1
    } else {
      right = mid - 1
    }
  }
  return -1
}

fn main() -> void {
  let mut numbers: i64[] = [64, 34, 25, 12, 22, 11, 90]
  println("Original: " + str(numbers))

  bubble_sort(&mut numbers)
  println("Sorted: " + str(numbers))

  let index = binary_search(numbers, 22)
  println("Index of 22: " + str(index))
}
