### 7. 최단 경로 찾기 (BFS)

```freelang
struct Graph {
  vertices: i64,
  edges: i64[][]
}

fn bfs(graph: &Graph, start: i64, end: i64) -> i64[] {
  let mut queue: i64[] = [start]
  let mut visited: bool[] = []
  let mut parent: i64[] = []

  let mut i = 0
  while i < graph.vertices {
    visited.push(false)
    parent.push(-1)
    i = i + 1
  }
  visited[start] = true

  while len(queue) > 0 {
    let node = queue[0]

    if node == end {
      break
    }

    for neighbor in graph.edges[node] {
      if !visited[neighbor] {
        visited[neighbor] = true
        parent[neighbor] = node
        queue.push(neighbor)
      }
    }

    queue = queue.slice(1, len(queue))
  }

  let mut path: i64[] = []
  let mut current = end
  while current != -1 {
    path.push(current)
    current = parent[current]
  }
  path.reverse()
  return path
}

fn main() -> void {
  // 예제 그래프 구성
  // 0 -> 1, 2
  // 1 -> 0, 3
  // 2 -> 0, 3
  // 3 -> 1, 2, 4
  // 4 -> 3

  println("BFS 경로 찾기 예제")
}
```

### 8. 동적 프로그래밍 (배낭 문제)

```freelang
fn knapsack(weights: i64[], values: i64[], capacity: i64) -> i64 {
  let n = len(weights)
  let mut dp: i64[][] = []

  let mut i = 0
  while i <= n {
    let mut row: i64[] = []
    let mut j = 0
    while j <= capacity {
      row.push(0)
      j = j + 1
    }
    dp.push(row)
    i = i + 1
  }

  i = 1
  while i <= n {
    let mut j = 1
    while j <= capacity {
      if weights[i - 1] <= j {
        let include = values[i - 1] + dp[i - 1][j - weights[i - 1]]
        let exclude = dp[i - 1][j]
        if include > exclude {
          dp[i][j] = include
        } else {
          dp[i][j] = exclude
        }
      } else {
        dp[i][j] = dp[i - 1][j]
      }
      j = j + 1
    }
    i = i + 1
  }

  return dp[n][capacity]
}

fn main() -> void {
  let weights: i64[] = [2, 3, 4, 5]
  let values: i64[] = [3, 4, 5, 6]
  let capacity = 8

  let max_value = knapsack(weights, values, capacity)
  println("Maximum value: " + str(max_value))
}
```

