/**
 * FreeLang Playground Backend Server
 * Handles code compilation, execution, and sharing
 */

const express = require('express');
const cors = require('cors');
const bodyParser = require('body-parser');
const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const app = express();
const PORT = process.env.PORT || 3000;

// Middleware
app.use(cors());
app.use(bodyParser.json({ limit: '50mb' }));
app.use(bodyParser.urlencoded({ limit: '50mb', extended: true }));

// 코드 저장 디렉토리
const CODE_DIR = path.join(__dirname, '.codes');
const SHARE_DIR = path.join(__dirname, '.share');

// 디렉토리 생성
if (!fs.existsSync(CODE_DIR)) {
  fs.mkdirSync(CODE_DIR, { recursive: true });
}
if (!fs.existsSync(SHARE_DIR)) {
  fs.mkdirSync(SHARE_DIR, { recursive: true });
}

// ============ API ENDPOINTS ============

/**
 * Health Check
 */
app.get('/api/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: '1.0.0'
  });
});

/**
 * 코드 컴파일
 * POST /api/compile
 * Body: { code: string, language: string }
 */
app.post('/api/compile', (req, res) => {
  try {
    const { code, language = 'freelang' } = req.body;

    if (!code) {
      return res.status(400).json({
        success: false,
        error: 'Code is required'
      });
    }

    // 임시 파일 생성
    const filename = `code_${Date.now()}.fl`;
    const filepath = path.join(CODE_DIR, filename);

    fs.writeFileSync(filepath, code);

    // 컴파일 실행 (freelang 컴파일러)
    exec(`freelang compile ${filepath}`, (error, stdout, stderr) => {
      fs.unlinkSync(filepath);

      if (error) {
        return res.json({
          success: false,
          error: stderr || error.message,
          stdout
        });
      }

      res.json({
        success: true,
        output: stdout,
        compilationTime: new Date().toISOString()
      });
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: error.message
    });
  }
});

/**
 * 코드 실행
 * POST /api/run
 * Body: { code: string, timeout: number }
 */
app.post('/api/run', (req, res) => {
  try {
    const { code, timeout = 5000 } = req.body;

    if (!code) {
      return res.status(400).json({
        success: false,
        error: 'Code is required'
      });
    }

    // 임시 파일 생성
    const filename = `code_${Date.now()}.fl`;
    const filepath = path.join(CODE_DIR, filename);

    fs.writeFileSync(filepath, code);

    // 코드 실행
    const startTime = Date.now();

    exec(`freelang run ${filepath}`, { timeout }, (error, stdout, stderr) => {
      fs.unlinkSync(filepath);

      const executionTime = Date.now() - startTime;

      if (error) {
        return res.json({
          success: false,
          error: stderr || error.message,
          stdout,
          executionTime,
          timedOut: error.killed
        });
      }

      res.json({
        success: true,
        output: stdout,
        executionTime,
        stderr: stderr || null
      });
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: error.message
    });
  }
});

/**
 * 코드 공유
 * POST /api/share
 * Body: { code: string, title: string, description: string }
 */
app.post('/api/share', (req, res) => {
  try {
    const { code, title = 'Untitled', description = '', tags = [] } = req.body;

    if (!code) {
      return res.status(400).json({
        success: false,
        error: 'Code is required'
      });
    }

    // 고유 ID 생성
    const shareId = crypto.randomBytes(8).toString('hex');
    const timestamp = new Date().toISOString();

    const shareData = {
      id: shareId,
      code,
      title,
      description,
      tags,
      createdAt: timestamp,
      updatedAt: timestamp,
      views: 0,
      url: `${req.protocol}://${req.get('host')}/playground?share=${shareId}`
    };

    // 공유 코드 저장
    fs.writeFileSync(
      path.join(SHARE_DIR, `${shareId}.json`),
      JSON.stringify(shareData, null, 2)
    );

    res.json({
      success: true,
      shareId,
      url: shareData.url
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: error.message
    });
  }
});

/**
 * 공유 코드 조회
 * GET /api/share/:shareId
 */
app.get('/api/share/:shareId', (req, res) => {
  try {
    const { shareId } = req.params;
    const filepath = path.join(SHARE_DIR, `${shareId}.json`);

    if (!fs.existsSync(filepath)) {
      return res.status(404).json({
        success: false,
        error: 'Share not found'
      });
    }

    const shareData = JSON.parse(fs.readFileSync(filepath, 'utf8'));

    // 조회수 증가
    shareData.views = (shareData.views || 0) + 1;
    shareData.updatedAt = new Date().toISOString();
    fs.writeFileSync(filepath, JSON.stringify(shareData, null, 2));

    res.json({
      success: true,
      data: shareData
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: error.message
    });
  }
});

/**
 * 모든 공유 코드 목록
 * GET /api/shares?page=1&limit=10&sort=views
 */
app.get('/api/shares', (req, res) => {
  try {
    const { page = 1, limit = 10, sort = 'views' } = req.query;
    const offset = (parseInt(page) - 1) * parseInt(limit);

    // 공유 폴더의 모든 파일 읽기
    const files = fs.readdirSync(SHARE_DIR).filter(f => f.endsWith('.json'));

    const shares = files.map(file => {
      const data = JSON.parse(fs.readFileSync(path.join(SHARE_DIR, file), 'utf8'));
      return data;
    });

    // 정렬
    if (sort === 'views') {
      shares.sort((a, b) => (b.views || 0) - (a.views || 0));
    } else if (sort === 'latest') {
      shares.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
    }

    // 페이지네이션
    const paginated = shares.slice(offset, offset + parseInt(limit));

    res.json({
      success: true,
      data: paginated,
      total: shares.length,
      page: parseInt(page),
      limit: parseInt(limit)
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: error.message
    });
  }
});

/**
 * 공유 코드 업데이트
 * PUT /api/share/:shareId
 * Body: { title, description, tags }
 */
app.put('/api/share/:shareId', (req, res) => {
  try {
    const { shareId } = req.params;
    const { title, description, tags } = req.body;
    const filepath = path.join(SHARE_DIR, `${shareId}.json`);

    if (!fs.existsSync(filepath)) {
      return res.status(404).json({
        success: false,
        error: 'Share not found'
      });
    }

    const shareData = JSON.parse(fs.readFileSync(filepath, 'utf8'));

    if (title) shareData.title = title;
    if (description) shareData.description = description;
    if (tags) shareData.tags = tags;
    shareData.updatedAt = new Date().toISOString();

    fs.writeFileSync(filepath, JSON.stringify(shareData, null, 2));

    res.json({
      success: true,
      data: shareData
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: error.message
    });
  }
});

/**
 * 공유 코드 삭제
 * DELETE /api/share/:shareId
 */
app.delete('/api/share/:shareId', (req, res) => {
  try {
    const { shareId } = req.params;
    const filepath = path.join(SHARE_DIR, `${shareId}.json`);

    if (!fs.existsSync(filepath)) {
      return res.status(404).json({
        success: false,
        error: 'Share not found'
      });
    }

    fs.unlinkSync(filepath);

    res.json({
      success: true,
      message: 'Share deleted'
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: error.message
    });
  }
});

/**
 * 예제 목록
 * GET /api/examples
 */
app.get('/api/examples', (req, res) => {
  const examples = [
    {
      id: 'hello-world',
      title: 'Hello World',
      description: '첫 번째 FreeLang 프로그램',
      code: `fn main() {
  println("Hello, FreeLang! 🚀")
}`
    },
    {
      id: 'fibonacci',
      title: 'Fibonacci',
      description: '피보나치 수열 계산',
      code: `fn fibonacci(n: i64) -> i64 {
  if n <= 1 { return n }
  return fibonacci(n - 1) + fibonacci(n - 2)
}

fn main() {
  for i in range(10) {
    println(str(fibonacci(i)))
  }
}`
    },
    {
      id: 'loop-example',
      title: 'Loop Example',
      description: '반복문 예제',
      code: `fn main() {
  // for 루프
  for i in range(5) {
    println("i = " + str(i))
  }

  // while 루프
  let mut x = 0
  while x < 3 {
    println("x = " + str(x))
    x = x + 1
  }
}`
    },
    {
      id: 'array-sort',
      title: 'Array Sort',
      description: '배열 정렬',
      code: `fn bubble_sort(arr: &mut i64[]) {
  let n = len(arr)
  let mut i = 0
  while i < n {
    let mut j = 0
    while j < n - i - 1 {
      if arr[j] > arr[j + 1] {
        let temp = arr[j]
        arr[j] = arr[j + 1]
        arr[j + 1] = temp
      }
      j = j + 1
    }
    i = i + 1
  }
}

fn main() {
  let mut nums: i64[] = [64, 34, 25, 12, 22, 11, 90]
  bubble_sort(&mut nums)
  println("Sorted!")
}`
    },
    {
      id: 'struct-example',
      title: 'Struct Example',
      description: '구조체 정의 및 사용',
      code: `struct Person {
  name: string,
  age: i64
}

fn main() {
  let person = Person {
    name: "Alice",
    age: 30
  }

  println("Name: " + person.name)
  println("Age: " + str(person.age))
}`
    }
  ];

  res.json({
    success: true,
    data: examples
  });
});

/**
 * 언어 정보
 * GET /api/info
 */
app.get('/api/info', (req, res) => {
  res.json({
    success: true,
    data: {
      name: 'FreeLang',
      version: '2.9.0',
      description: 'Zero-Dependency AI Compiler',
      features: [
        'Self-hosting',
        'Zero-dependency',
        '1,340+ built-in functions',
        'Native linter',
        'Native GraphQL',
        'Native test framework'
      ],
      documentation: 'https://freelang.io/docs',
      github: 'https://github.com/freelang-io/freelang-compiler',
      discord: 'https://discord.gg/freelang'
    }
  });
});

// ============ ERROR HANDLING ============

app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({
    success: false,
    error: 'Internal Server Error',
    message: err.message
  });
});

// ============ SERVER START ============

app.listen(PORT, () => {
  console.log(`
╔════════════════════════════════════════╗
║   FreeLang Playground Server Started   ║
╚════════════════════════════════════════╝

  📍 Server: http://localhost:${PORT}
  🎮 Playground: http://localhost:3001
  📚 API Docs: http://localhost:${PORT}/api/health

  Available Endpoints:
  ✓ POST   /api/compile      - Compile code
  ✓ POST   /api/run          - Run code
  ✓ POST   /api/share        - Share code
  ✓ GET    /api/share/:id    - Get shared code
  ✓ GET    /api/shares       - List all shared
  ✓ PUT    /api/share/:id    - Update share
  ✓ DELETE /api/share/:id    - Delete share
  ✓ GET    /api/examples     - Get examples
  ✓ GET    /api/info         - Get language info
  ✓ GET    /api/health       - Health check

  Quit: press CTRL+C
  `);
});

module.exports = app;

