  }
});

/**
 * 예제 목록
 * GET /api/examples
 */
app.get('/api/examples', (req, res) => {
  const examples = [
    {
      id: 'hello-world',
      title: 'Hello World',
      description: '첫 번째 FreeLang 프로그램',
      code: `fn main() {
  println("Hello, FreeLang! 🚀")
}`
    },
    {
      id: 'fibonacci',
      title: 'Fibonacci',
      description: '피보나치 수열 계산',
      code: `fn fibonacci(n: i64) -> i64 {
  if n <= 1 { return n }
  return fibonacci(n - 1) + fibonacci(n - 2)
}

fn main() {
  for i in range(10) {
    println(str(fibonacci(i)))
  }
}`
    },
    {
      id: 'loop-example',
      title: 'Loop Example',
      description: '반복문 예제',
      code: `fn main() {
  // for 루프
  for i in range(5) {
    println("i = " + str(i))
  }

  // while 루프
  let mut x = 0
  while x < 3 {
    println("x = " + str(x))
    x = x + 1
  }
}`
    },
    {
      id: 'array-sort',
      title: 'Array Sort',
      description: '배열 정렬',
      code: `fn bubble_sort(arr: &mut i64[]) {
  let n = len(arr)
  let mut i = 0
  while i < n {
    let mut j = 0
    while j < n - i - 1 {
      if arr[j] > arr[j + 1] {
        let temp = arr[j]
        arr[j] = arr[j + 1]
        arr[j + 1] = temp
      }
      j = j + 1
    }
    i = i + 1
  }
}

fn main() {
  let mut nums: i64[] = [64, 34, 25, 12, 22, 11, 90]
  bubble_sort(&mut nums)
  println("Sorted!")
}`
    },
    {
      id: 'struct-example',
      title: 'Struct Example',
      description: '구조체 정의 및 사용',
      code: `struct Person {
  name: string,
  age: i64
}

fn main() {
  let person = Person {
    name: "Alice",
    age: 30
  }

  println("Name: " + person.name)
  println("Age: " + str(person.age))
}`
    }
  ];

  res.json({
    success: true,
    data: examples
  });
});

/**
 * 언어 정보
 * GET /api/info
 */
app.get('/api/info', (req, res) => {
  res.json({
    success: true,
    data: {
      name: 'FreeLang',
      version: '2.9.0',
      description: 'Zero-Dependency AI Compiler',
      features: [
        'Self-hosting',
        'Zero-dependency',
        '1,340+ built-in functions',
        'Native linter',
        'Native GraphQL',
        'Native test framework'
      ],
      documentation: 'https://freelang.io/docs',
      github: 'https://github.com/freelang-io/freelang-compiler',
      discord: 'https://discord.gg/freelang'
    }
  });
});

// ============ ERROR HANDLING ============

app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({
    success: false,
    error: 'Internal Server Error',
    message: err.message
  });
});

// ============ SERVER START ============

app.listen(PORT, () => {
  console.log(`
╔════════════════════════════════════════╗
║   FreeLang Playground Server Started   ║
╚════════════════════════════════════════╝

  📍 Server: http://localhost:${PORT}
  🎮 Playground: http://localhost:3001
  📚 API Docs: http://localhost:${PORT}/api/health

  Available Endpoints:
  ✓ POST   /api/compile      - Compile code
  ✓ POST   /api/run          - Run code
  ✓ POST   /api/share        - Share code
  ✓ GET    /api/share/:id    - Get shared code
  ✓ GET    /api/shares       - List all shared
  ✓ PUT    /api/share/:id    - Update share
  ✓ DELETE /api/share/:id    - Delete share
  ✓ GET    /api/examples     - Get examples
  ✓ GET    /api/info         - Get language info
  ✓ GET    /api/health       - Health check

  Quit: press CTRL+C
  `);
});

module.exports = app;

