/**
 * FreeLang Playground API Client
 * 프론트엔드에서 백엔드 API를 호출하는 클라이언트
 */

class PlaygroundAPI {
  constructor(baseURL = 'http://localhost:3000/api') {
    this.baseURL = baseURL;
  }

  /**
   * API 요청 헬퍼
   */
  async request(endpoint, options = {}) {
    const url = `${this.baseURL}${endpoint}`;
    const config = {
      headers: {
        'Content-Type': 'application/json',
        ...options.headers
      },
      ...options
    };

    try {
      const response = await fetch(url, config);
      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || 'API Error');
      }

      return data;
    } catch (error) {
      console.error(`API Error: ${endpoint}`, error);
      throw error;
    }
  }

  /**
   * 건강 상태 확인
   */
  async health() {
    return this.request('/health');
  }

  /**
   * 코드 컴파일
   */
  async compile(code, language = 'freelang') {
    return this.request('/compile', {
      method: 'POST',
      body: JSON.stringify({ code, language })
    });
  }

  /**
   * 코드 실행
   */
  async run(code, timeout = 5000) {
    return this.request('/run', {
      method: 'POST',
      body: JSON.stringify({ code, timeout })
    });
  }

  /**
   * 코드 공유
   */
  async share(code, title = 'Untitled', description = '', tags = []) {
    return this.request('/share', {
      method: 'POST',
      body: JSON.stringify({ code, title, description, tags })
    });
  }

  /**
   * 공유 코드 조회
   */
  async getShare(shareId) {
    return this.request(`/share/${shareId}`);
  }

  /**
   * 공유 코드 목록
   */
  async listShares(page = 1, limit = 10, sort = 'views') {
    return this.request(`/shares?page=${page}&limit=${limit}&sort=${sort}`);
  }

  /**
   * 공유 코드 업데이트
   */
  async updateShare(shareId, { title, description, tags }) {
    return this.request(`/share/${shareId}`, {
      method: 'PUT',
      body: JSON.stringify({ title, description, tags })
    });
  }

  /**
   * 공유 코드 삭제
   */
  async deleteShare(shareId) {
    return this.request(`/share/${shareId}`, {
      method: 'DELETE'
    });
  }

  /**
   * 예제 목록
   */
  async getExamples() {
    return this.request('/examples');
  }

  /**
   * 언어 정보
   */
  async getInfo() {
    return this.request('/info');
  }
}

